"use client";

import Link from "next/link";
import { memo, useEffect, useMemo, useState, type ReactNode, type RefObject } from "react";
import { cn } from "cn";
import { Tooltip } from "./tooltip";
import { LazyMotion, domAnimation, useReducedMotion } from "motion/react";
import * as m from "motion/react-m";

/** Inspired by Devouring Details and Skiper UI. */
const MotionLink = m.create(Link);
const LINE_WIDTHS = { sm: [32, 24, 20, 16], md: [56, 44, 36, 28] };
const PROXIMITY_RADIUS = 40;

export type NavLineItem = {
  id: string;
  label: string;
  /** Navigate instead of scrolling to a section. */
  href?: string;
  card?: { title: string; description?: string; icon?: ReactNode };
};

export type NavLineProps = {
  items?: NavLineItem[];
  activeId?: string;
  showLabels?: boolean;
  size?: "sm" | "md";
  variant?: "viewport" | "contained";
  scrollRootRef?: RefObject<HTMLElement | null>;
  onSectionClick?: (targetSectionId: string, currentSectionId?: string) => void;
  className?: string;
};

const EMPTY_ITEMS: NavLineItem[] = [];

const ProximityDash = memo(function ProximityDash({
  width,
  reducedMotion,
  highlighted,
}: {
  width: number;
  reducedMotion: boolean | null;
  highlighted: boolean;
}) {
  return (
    <m.span
      aria-hidden="true"
      data-nav-line=""
      className={cn("block h-px shrink-0 transition-colors group-hover:bg-foreground group-focus-visible:bg-foreground group-aria-[current=page]:bg-foreground group-aria-[current=location]:bg-foreground", highlighted ? "bg-foreground" : "bg-muted-foreground/40")}
      initial={false}
      animate={{ width }}
      transition={reducedMotion ? { duration: 0 } : { type: "spring", stiffness: 320, damping: 34, mass: 0.7 }}
    />
  );
});

export const NavLine = memo(function NavLine({
  items = EMPTY_ITEMS,
  activeId,
  showLabels = false,
  size = "md",
  variant = "viewport",
  scrollRootRef,
  onSectionClick,
  className,
}: NavLineProps = {}) {
  const reducedMotion = useReducedMotion();
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [proximityIndex, setProximityIndex] = useState<number | null>(null);
  const [tracked, setTracked] = useState(() => items[0]?.id ?? "");
  const active = activeId ?? (items.some(item => item.id === tracked) ? tracked : items[0]?.id);
  const scrollIds = useMemo(() => items.filter(item => !item.href).map(item => item.id), [items]);

  useEffect(() => {
    if (!scrollIds.length || activeId !== undefined) return;

    const startTracking = () => {
      const scrollRoot = scrollRootRef?.current ?? null;
      const targets = scrollIds.map(id => document.getElementById(id))
        .filter((target): target is HTMLElement => Boolean(target && (!scrollRoot || scrollRoot.contains(target))));
      if (!targets.length) return () => {};

      const visible = new Set<HTMLElement>();
      const pickClosest = () => {
        const rootTop = scrollRoot?.getBoundingClientRect().top ?? 0;
        const rootHeight = scrollRoot?.clientHeight ?? window.innerHeight;
        const bandCenter = rootTop + rootHeight * 0.4;
        let closest: HTMLElement | undefined;
        let bestDistance = Infinity;
        for (const target of targets) {
          if (!visible.has(target)) continue;
          const distance = Math.abs(target.getBoundingClientRect().top - bandCenter);
          if (distance < bestDistance) {
            closest = target;
            bestDistance = distance;
          }
        }
        if (closest) setTracked(closest.id);
      };
      const observer = new IntersectionObserver(entries => {
        for (const entry of entries) {
          const target = entry.target as HTMLElement;
          if (entry.isIntersecting) visible.add(target);
          else visible.delete(target);
        }
        pickClosest();
      }, { root: scrollRoot, rootMargin: "-25% 0px -45% 0px", threshold: 0 });
      targets.forEach(target => observer.observe(target));

      const onScroll = () => {
        const scrollHeight = scrollRoot?.scrollHeight ?? document.documentElement.scrollHeight;
        const clientHeight = scrollRoot?.clientHeight ?? window.innerHeight;
        const scrollTop = scrollRoot?.scrollTop ?? window.scrollY;
        if (scrollHeight > clientHeight && scrollHeight - scrollTop - clientHeight < 4) {
          setTracked(targets[targets.length - 1].id);
        } else {
          pickClosest();
        }
      };
      const source = scrollRoot ?? window;
      source.addEventListener("scroll", onScroll, { passive: true });
      return () => {
        observer.disconnect();
        source.removeEventListener("scroll", onScroll);
      };
    };

    if (variant === "contained") return startTracking();
    const query = window.matchMedia("(min-width: 64rem)");
    let teardown: (() => void) | undefined;
    const syncTracking = () => {
      if (query.matches && !teardown) teardown = startTracking();
      else if (!query.matches && teardown) {
        teardown();
        teardown = undefined;
      }
    };
    syncTracking();
    query.addEventListener("change", syncTracking);
    return () => {
      query.removeEventListener("change", syncTracking);
      teardown?.();
    };
  }, [scrollIds, scrollRootRef, variant, activeId]);

  const scrollTo = (id: string) => {
    const scrollRoot = scrollRootRef?.current ?? null;
    const target = document.getElementById(id);
    if (!target || (scrollRoot && !scrollRoot.contains(target))) return;
    onSectionClick?.(id, active);
    setTracked(id);
    const behavior = window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth";
    if (scrollRoot) {
      scrollRoot.scrollTo({
        top: scrollRoot.scrollTop + target.getBoundingClientRect().top - scrollRoot.getBoundingClientRect().top - scrollRoot.clientTop,
        behavior,
      });
    } else target.scrollIntoView({ behavior, block: "start" });
  };

  const widths = LINE_WIDTHS[size];
  const activeIndex = Math.max(0, items.findIndex(item => item.id === active));
  const trackPointer = (event: React.PointerEvent<HTMLElement>) => {
    const dashes = [...event.currentTarget.querySelectorAll<HTMLElement>("[data-nav-line]")];
    let closestIndex: number | null = null;
    let closestDistance = PROXIMITY_RADIUS;
    dashes.forEach((dash, index) => {
      const rect = dash.getBoundingClientRect();
      const distance = Math.abs(event.clientY - (rect.top + rect.height / 2));
      if (distance < closestDistance) {
        closestIndex = index;
        closestDistance = distance;
      }
    });
    setProximityIndex(closestIndex);
  };

  return (
    <LazyMotion features={domAnimation} strict>
      <nav aria-label="Sections" onPointerMove={trackPointer} onPointerLeave={() => { setHoveredIndex(null); setProximityIndex(null); }} className={cn(
        "top-1/2 left-0 z-30 -translate-y-1/2 flex-col items-start gap-2",
        variant === "contained" ? "absolute flex" : "fixed hidden lg:flex",
        className,
      )}>
        <div aria-hidden="true" className="absolute inset-y-1 left-0 border-l border-dashed border-border/60" />
        {items.map((item, index) => {
          const isActive = active === item.id;
          const isSelected = isActive || hoveredIndex === index || proximityIndex === index;
          const activeWidth = widths[Math.min(Math.abs(activeIndex - index), widths.length - 1)];
          const hoverIndex = proximityIndex ?? hoveredIndex;
          const hoverWidth = hoverIndex === null ? 0 : widths[Math.min(Math.abs(hoverIndex - index), widths.length - 1)];
          const width = Math.max(activeWidth, hoverWidth);
          const highlighted = isSelected;
          const rowClass = "group relative -my-1.5 flex cursor-pointer items-center gap-3 py-1.5 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring";
          const contents = <>
            <ProximityDash width={width} reducedMotion={reducedMotion} highlighted={highlighted} />
            {showLabels && <span data-nav-label="" className="whitespace-nowrap text-sm text-muted-foreground transition-colors group-hover:text-foreground group-focus-visible:text-foreground group-aria-[current=page]:text-foreground group-aria-[current=location]:text-foreground motion-reduce:transition-none">{item.label}</span>}
          </>;
          return (
              <Tooltip key={item.id} side="right" sideOffset={10}
                className={item.card ? "w-60" : undefined}
                title={item.card?.title} description={item.card?.description} icon={item.card?.icon}
                content={item.card ? undefined : item.label}
              >
                {item.href ? (
                  <MotionLink href={item.href} aria-label={item.label} aria-current={isActive ? "page" : undefined}
                    initial={variant === "contained" && !reducedMotion ? { opacity: 0, y: 5 } : false}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: reducedMotion ? 0 : 0.16, delay: variant === "contained" && !reducedMotion ? index * 0.03 : 0 }}
                    className={rowClass} onHoverStart={() => setHoveredIndex(index)} onFocus={() => setHoveredIndex(index)} onBlur={() => setHoveredIndex(null)}>
                    {contents}
                  </MotionLink>
                ) : (
                  <m.button type="button" aria-label={item.label} aria-current={isActive ? "location" : undefined}
                    initial={variant === "contained" && !reducedMotion ? { opacity: 0, y: 5 } : false}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: reducedMotion ? 0 : 0.16, delay: variant === "contained" && !reducedMotion ? index * 0.03 : 0 }}
                    onClick={() => scrollTo(item.id)} className={rowClass} onHoverStart={() => setHoveredIndex(index)} onFocus={() => setHoveredIndex(index)} onBlur={() => setHoveredIndex(null)}>
                    {contents}
                  </m.button>
                )}
              </Tooltip>

          );
        })}
      </nav>
    </LazyMotion>
  );
});

import { typography } from "../lib/typography.shared";
import type { ComponentProps, ReactNode } from "react";

interface CardProps extends Omit<ComponentProps<"article">, "title"> {
  title?: string;
  description?: string;
  footer?: ReactNode;
}

export function Card({ title = "Room for your next idea", description = "A simple starting point for something great. Make it yours.", children, footer, className = "", ...props }: CardProps = {}) {
  return <article className={`w-full max-w-sm border border-border bg-card p-6 text-base leading-7 text-card-foreground shadow-sm ${className}`} {...props}>
    {title && <h3 className={typography.sectionTitle}>{title}</h3>}
    {description && <p className={`mt-2 ${typography.body}`}>{description}</p>}
    {children && <div className={title || description || footer ? "mt-5" : "h-full min-h-0"}>{children}</div>}
    {footer && <footer className="mt-5 border-t border-border pt-4">{footer}</footer>}
  </article>;
}

"use client";

import { typography } from "../lib/typography.shared";
import {
  cloneElement,
  useEffect,
  useId,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
} from "react";
import { cn } from "cn";
import { Card } from "./card";
import { AnimatePresence, LazyMotion, domAnimation, useReducedMotion } from "motion/react";
import * as m from "motion/react-m";

export type TooltipProps = {
  /** A single focusable button or link. */
  children?: ReactElement<HTMLAttributes<HTMLElement>>;
  title?: string;
  description?: string;
  icon?: ReactNode;
  content?: ReactNode;
  side?: "top" | "right" | "bottom" | "left";
  sideOffset?: number;
  className?: string;
};

const positions = {
  top: "bottom-full left-1/2 -translate-x-1/2 pb-[var(--tooltip-offset)]",
  right: "left-full top-1/2 -translate-y-1/2 pl-[var(--tooltip-offset)]",
  bottom: "top-full left-1/2 -translate-x-1/2 pt-[var(--tooltip-offset)]",
  left: "right-full top-1/2 -translate-y-1/2 pr-[var(--tooltip-offset)]",
};

export function Tooltip({
  children = (
    <button
      type="button"
      className="border border-border px-4 py-2 text-sm focus-visible:outline-2 focus-visible:outline-ring"
    >
      Hover or focus me
    </button>
  ),
  title,
  description,
  icon,
  content,
  side = "top",
  sideOffset = 10,
  className,
}: TooltipProps = {}) {
  const id = useId();
  const [open, setOpen] = useState(false);
  const reducedMotion = useReducedMotion();
  const offset = side === "top" ? { y: 4 } : side === "bottom" ? { y: -4 } : side === "left" ? { x: 4 } : { x: -4 };

  useEffect(() => {
    if (!open) return;
    const dismiss = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("keydown", dismiss);
    return () => document.removeEventListener("keydown", dismiss);
  }, [open]);

  return (
    <LazyMotion features={domAnimation} strict>
    <div
      className="relative inline-flex"
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={(event) => {
        if (!event.currentTarget.querySelector(":focus-visible"))
          setOpen(false);
      }}
      onFocusCapture={(event) => {
        if (event.target.matches(":focus-visible")) setOpen(true);
      }}
      onBlurCapture={(event) => {
        if (
          !event.currentTarget.contains(event.relatedTarget) &&
          !event.currentTarget.matches(":hover")
        )
          setOpen(false);
      }}
      style={
        { "--tooltip-offset": `${Math.max(0, sideOffset)}px` } as CSSProperties
      }
    >
      {cloneElement(children, {
        "aria-describedby": [children.props["aria-describedby"], id]
          .filter(Boolean)
          .join(" "),
      })}
      <div
        id={id}
        role="tooltip"
        aria-hidden={!open}
        className={cn(
          "absolute z-50 w-max max-w-[min(20rem,calc(100vw-2rem))]",
          positions[side],
        )}
      >
        <AnimatePresence initial={false}>
        {open && <m.div
          key="tooltip-panel"
          initial={reducedMotion ? false : { opacity: 0, scale: 0.98, ...offset }}
          animate={{ opacity: 1, scale: 1, x: 0, y: 0 }}
          exit={reducedMotion ? undefined : { opacity: 0, scale: 0.98, ...offset }}
          transition={{ duration: reducedMotion ? 0 : 0.16, ease: "easeOut" }}
        >
        <Card
          title=""
          description=""
          className={cn(
            "w-max max-w-full shadow-lg",
            title || description
              ? "w-64 p-3! text-base"
              : "px-3! py-1.5! text-base leading-7",
            className,
          )}
        >
          <div className="flex items-start gap-3">
            {icon && (
              <span
                aria-hidden="true"
                className="flex size-8 shrink-0 items-center justify-center border border-primary/20 bg-primary/10 text-primary"
              >
                {icon}
              </span>
            )}
            <div className="min-w-0 text-left">
              {title && (
                <p className="text-base font-semibold leading-snug text-foreground">
                  {title}
                </p>
              )}
              {description && (
                <p
                  className={cn(
                    typography.caption,
                    title && "mt-1.5",
                  )}
                >
                  {description}
                </p>
              )}
              {content && (
                <div className={cn((title || description) && "mt-2")}>
                  {content}
                </div>
              )}
              {!title &&
                !description &&
                !content &&
                "A little extra context, right when you need it."}
            </div>
          </div>
        </Card>
        </m.div>}
        </AnimatePresence>
      </div>
    </div>
    </LazyMotion>
  );
}

/** Shared text hierarchy for documentation and component content. */
export const typography = {
  pageTitle: "text-4xl font-semibold tracking-tight text-foreground sm:text-5xl",
  sectionTitle: "text-2xl font-semibold tracking-tight text-foreground",
  subsectionTitle: "text-xl font-semibold tracking-tight text-foreground",
  body: "text-base leading-7 text-muted-foreground",
  label: "text-sm font-medium",
  caption: "text-sm leading-6 text-muted-foreground",
} as const;
